T.update({'goal_title': 'இன்றைய இலக்கு', 'goal_sub': 'இரவு ஓய்வு நேரம் முடிந்தது. போனைப் பயன்படுத்தும் முன் இன்றைய இலக்கை முடிவுசெய்யுங்கள்.', 'goal_yesterday': 'நேற்றைய இலக்கு: %1$s', 'goal_hint': 'எ.கா. அறிக்கையை முடிப்பது', 'goal_start': 'முடிவுசெய்து நாளைத் தொடங்கு', 'goal_note': 'முடிவுசெய்யும் வரை பிற ஆப்ஸைத் திறந்தாலும் இங்கேயே திரும்புவீர்கள் (அழைப்புகள் செய்யலாம்). இலக்கை முகப்புத் திரையில் "இன்றைய இலக்கு" மூலம் காட்டலாம்.', 'goal_empty': 'இன்றைய இலக்கை அமைக்க தொடவும்', 's_goal_on': 'இரவு ஓய்வுக்குப் பிறகு முதலில் இன்றைய இலக்கை முடிவுசெய் (அதுவரை போன் பூட்டப்பட்டிருக்கும்)'})
